// SCENARIO: TEST 08 — CSV Variable Form Fill (dùng với test-data.csv)
import { test } from '@playwright/test';

// How long a step waits for its element, as set in the export.
const TIMEOUT = 10000;
test.use({ actionTimeout: TIMEOUT });

// An Input as the extension makes it: a <select>, a date, time, color or range field
// through its own setter (a typed date follows the browser's locale); any other field filled.
const _setInput = (el, value) => {
  el.scrollIntoView({ behavior: 'auto', block: 'center' });
  el.focus();
  const v = value ?? '';
  if (el.isContentEditable) {
    document.execCommand('selectAll', false, null);
    document.execCommand('insertText', false, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return;
  }
  if (el.tagName === 'SELECT') {
    const want = String(v);
    const options = Array.from(el.options);
    const option = options.find(o => o.value === want) || options.find(o => o.text === want);
    if (!option) throw new Error('The dropdown has no option "' + want + '"');
    el.value = option.value;
    el.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));
    el.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
    el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
    return;
  }
  let setter = null;
  for (let p = Object.getPrototypeOf(el); p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {
    const d = Object.getOwnPropertyDescriptor(p, 'value');
    if (d?.set) { setter = d.set; break; }
  }
  if (setter) setter.call(el, v); else el.value = v;
  el.dispatchEvent(new Event('input', { bubbles: true }));
  el.dispatchEvent(new Event('change', { bubbles: true }));
  el.dispatchEvent(new Event('blur', { bubbles: true }));
};
const _SCRIPT_INPUT_TYPES = ['date', 'time', 'datetime-local', 'month', 'week', 'color', 'range'];
async function _input(el, value) {
  const kind = await el.evaluate((e) => (e.tagName === 'SELECT' ? 'select' : e.type));
  if (kind === 'select' || _SCRIPT_INPUT_TYPES.includes(kind)) await el.evaluate(_setInput, value);
  else await el.fill(value);
}

// A value inlined into script code, escaped as the extension escapes it (_applyVarsToCode).
const _js = (v) => String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/'/g, "\\'")
  .replace(/`/g, '\\`').replace(/\$\{/g, '\\${').replace(/\n/g, '\\n').replace(/\r/g, '\\r');

